  ('5. ディープラーニングの要素技術', '#d2a8ff', 4),
  ('6. ディープラーニングの応用例', '#f0883e', 5),
  ('7. AIの社会実装に向けて', '#e3b341', 6),
  ('8. AIに必要な数理・統計知識', '#39c5cf', 7),
  ('9. AIに関する法律と契約', '#f85149', 8),
  ('10. AI倫理・AIガバナンス', '#ff7b72', 9)
) AS v(name, color, sort_order)
WHERE s.slug = 'g-kentei-d'
ON CONFLICT (subject_id, name) DO NOTHING;
COMMIT;
BEGIN;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-d-q1', '特定の作業だけでなく、人間のように幅広い課題に柔軟に対応できるとされる、まだ実現していないAIを指す語はどれか。', NULL, '["汎用人工知能（AGI）", "特化型AI", "エキスパートシステム", "強化学習エージェント"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "幅広い課題に柔軟に対応できる、まだ実現していないAIを指す語は？", "point": "「特定作業に限らず、人間のように幅広くこなす(まだ未実現の)AI」なら、汎用人工知能(AGI)。", "kid": "今のAIは「翻訳だけ」「囲碁だけ」と一つの作業に特化している。人間のように何でも柔軟にこなせるAIが汎用人工知能(AGI)。まだ実現していない目標。", "eg": "一芸に秀でた専門家(今のAI)に対して、何でもそつなくこなす“万能な人”を目指す、あのイメージ。", "terms": [["汎用人工知能（AGI）", "特定の作業に限らず、人間のように幅広い課題に対応できるとされるAI。まだ実現していない"], ["特化型AI", "特定の作業だけに特化したAI。現状のAIの大半がこれ"]], "think": "「幅広く柔軟・人間並み・まだ未実現」なら汎用人工知能(AGI)。一つの作業だけの特化型AIと対で押さえる。", "vs": "特化型AIは特定作業専用の現状のAI、エキスパートシステムは知識をルール化した古典的AI、強化学習エージェントは報酬で学ぶ仕組みで、いずれも幅広くこなす汎用人工知能ではない。", "usecase": "AIの最終目標としてよく語られる概念。今のAIがどこまで来ているか、何が足りないかを議論する基準になる。", "opt": ["正解。幅広い課題に柔軟に対応できるとされる未実現のAIが汎用人工知能。", "特定作業だけに特化した現状のAIで、幅広くこなす汎用ではない。", "知識をルール化した古典的AIで、汎用人工知能ではない。", "報酬で学ぶ仕組みで、幅広くこなす汎用AIそのものではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-d' AND c.name='1. 人工知能とは'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-d-q2', 'AIの能力段階のうち、人間が与えたデータから入力と出力の対応ルールそのものを学習して獲得する（機械学習を取り入れた）段階はどれか。', NULL, '["対応のルールをデータから学習する段階", "決められた振る舞いしかしない制御の段階", "対応関係を人間がすべて定義する段階", "特徴量そのものまで自ら学習する段階"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "入力と出力の対応ルールを、データから学習する(機械学習を取り入れた)段階は？", "point": "「対応のルールをデータから自分で学ぶ(機械学習を取り入れた)」なら、レベル3。", "kid": "人が対応を全部決める段階(レベル2)より一歩進み、データから「こういう入力にはこう返す」というルール自体を学ぶ段階。機械学習を取り入れたAIがこれにあたる。ただし注目する特徴は人が用意する。", "eg": "大量の例題を解くうちに「解き方のパターン」を自分でつかむ、あの学び方。ただしどの手がかりに注目するかは先生が示す。", "terms": [["レベル3", "入力と出力の対応ルールをデータから学習する段階。機械学習を取り入れたAI"], ["レベル4", "注目すべき特徴量まで自ら学習する最上位の段階。ディープラーニング相当"]], "think": "「対応ルールをデータから学ぶ・特徴は人が用意」ならレベル3。特徴まで自分で学ぶレベル4の一歩手前。", "vs": "決められた動きだけの制御は最も単純な段階、対応を人が全部定義するのは一つ手前の段階、特徴量まで自ら学ぶのは最上位の段階で、いずれも機械学習を取り入れたレベル3そのものではない。", "usecase": "「機械学習を使うAI」がどの段階かを整理する軸。特徴を人が設計する従来の機械学習と、特徴も学ぶディープラーニングの違いを捉える土台。", "opt": ["正解。対応ルールをデータから学習する、機械学習を取り入れた段階。", "決められた動きだけの最も単純な段階で、学習していない。", "対応を人が全部定義する段階で、ルールを学んでいない。", "特徴量まで自ら学ぶ最上位の段階で、レベル3の一つ上。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-d' AND c.name='1. 人工知能とは'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-d-q3', 'AIの2大アプローチのうち、脳の神経回路をまねてデータから学習させる立場（ニューラルネットワークなど）を指す語はどれか。', NULL, '["結合主義", "記号主義", "行動主義", "経験主義"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "脳の神経回路をまねてデータから学習させるAIの立場は？", "point": "「脳をまねてデータから学習させる(ニューラルネット的)立場」なら、結合主義。", "kid": "AIには2つの大きな流派がある。人が知識をルールで書き込む「記号主義」と、脳の神経回路をまねてデータから学ばせる「結合主義」。今のディープラーニングは結合主義の流れ。", "eg": "料理でいえば、レシピを全部文字で書き起こす流派(記号主義)と、たくさん食べ比べて舌で覚える流派(結合主義)の違い。", "terms": [["結合主義（コネクショニズム）", "脳の神経回路をまねてデータから学習させる立場。ニューラルネットワークが代表"], ["記号主義（シンボリズム）", "知識を記号やルールで表して推論させる立場。エキスパートシステムが代表"]], "think": "「脳をまねてデータから学ぶ」なら結合主義、「ルールで知識を書き込む」なら記号主義。学ぶか書き込むかで分ける。", "vs": "記号主義はルールで知識を書き込む立場、行動主義や経験主義は心理学・哲学の立場で、いずれも脳をまねて学ぶ結合主義ではない。", "usecase": "ディープラーニング(結合主義)と、エキスパートシステム(記号主義)がなぜ性質が違うのかを、根っこの考え方から理解できる。", "opt": ["正解。脳をまねてデータから学習させる立場が結合主義。", "知識をルールで書き込む立場で、データから学ぶ結合主義とは逆。", "心理学の立場で、AIの学習アプローチそのものではない。", "哲学の立場で、AIのアプローチそのものではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-d' AND c.name='1. 人工知能とは'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-d-q4', '囲碁・翻訳・画像認識のように、決められた一つの作業に特化して能力を発揮する、現状の大半を占めるAIを指す語はどれか。', NULL, '["特化型AI", "汎用人工知能", "エキスパートシステム", "強いAI"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "決められた一つの作業に特化して能力を発揮する、現状の大半のAIは？", "point": "「一つの決まった作業に特化した(現状の大半の)AI」なら、特化型AI。", "kid": "今のAIは、囲碁なら囲碁、翻訳なら翻訳と、一つの作業に絞って力を発揮する。何でもこなせるわけではない。この“一芸特化”が特化型AIで、現状のAIの大半がこれ。", "eg": "どんな料理も作れる万能シェフ(汎用AI)ではなく、寿司だけを極めた職人(特化型AI)のイメージ。", "terms": [["特化型AI", "決められた一つの作業に特化して力を発揮するAI。現状の大半がこれ"], ["汎用人工知能（AGI）", "幅広い課題に柔軟に対応できるとされるAI。まだ実現していない"]], "think": "「一つの作業に特化・現状の大半」なら特化型AI。幅広くこなす汎用人工知能(未実現)と対で押さえる。", "vs": "汎用人工知能は幅広くこなす未実現のAI、エキスパートシステムは知識をルール化した古典的AI、強いAIは本物の意識を持てるとする立場で、いずれも一芸特化の特化型AIそのものではない。", "usecase": "「AIはすごい」と一括りにせず、実際は一つの作業に特化していると理解するための基本。過度な期待を避ける現実的な視点になる。", "opt": ["正解。一つの作業に特化して力を発揮する現状の大半のAIが特化型AI。", "幅広くこなす未実現のAIで、一芸特化とは逆。", "知識をルール化した古典的AIで、特化型AIの分類そのものではない。", "本物の意識を持てるとする立場で、能力範囲の分類ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-d' AND c.name='1. 人工知能とは'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-d-q5', 'AIへの過度な期待が実際の成果に届かず、研究への関心や資金が急速に冷え込んだ時期を指す語はどれか。', NULL, '["AIの冬", "シンギュラリティ", "ムーアの法則", "AI効果"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "期待が成果に届かず、関心や資金が冷え込んだ時期を指す語は？", "point": "「ブームが去り、研究への関心や資金が冷え込んだ時期」なら、AIの冬。", "kid": "AIは何度も「すごい」と期待されてブームになったが、期待ほどの成果が出ないと、関心も研究資金も急に冷え込んだ。この冷え込みの時期をAIの冬と呼ぶ。ブームと冬を繰り返してきた。", "eg": "大ブームで盛り上がった商品が、期待外れと分かった途端に売れ行きも投資も一気に冷える、あの反動。", "terms": [["AIの冬", "AIへの期待が成果に届かず、研究への関心や資金が冷え込んだ時期"], ["AIブーム", "AIへの期待が高まり研究が盛んになる時期。冬と交互に繰り返してきた"]], "think": "「期待外れで関心・資金が冷え込んだ時期」ならAIの冬。AIが人間を超える未来のシンギュラリティとは正反対の局面。", "vs": "シンギュラリティはAIが人間を超える未来、ムーアの法則は半導体の性能向上の経験則、AI効果は仕組みが分かると知能扱いされなくなる心理で、いずれも研究が冷え込むAIの冬ではない。", "usecase": "AIの歴史がブームと冬の繰り返しだと理解する鍵。今のブームも過度な期待には注意、という教訓を読み取れる。", "opt": ["正解。期待が成果に届かず関心や資金が冷え込んだ時期がAIの冬。", "AIが人間を超える未来を指す語で、冷え込む局面とは逆。", "半導体の性能向上の経験則で、AIの盛衰の話ではない。", "仕組みが分かると知能扱いされなくなる心理で、冬とは別。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-d' AND c.name='2. 人工知能をめぐる動向'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-d-q6', '大学入試の突破を目標に掲げた日本のAIプロジェクトで、文章の意味理解の難しさという限界を示したものはどれか。', NULL, '["東ロボくん", "AlphaGo", "Watson", "ELIZA"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "大学入試突破を目標に、文章の意味理解の限界を示した日本のAIプロジェクトは？", "point": "「大学入試の突破を目指し、読解の限界を示した日本のプロジェクト」なら、東ロボくん。", "kid": "「AIは東大に合格できるか」に挑んだ日本のプロジェクト。暗記や計算は得意でも、文章の“意味”を理解する読解が壁となり、難関大の合格には届かなかった。AIの意味理解の難しさを示した。", "eg": "暗記科目は高得点なのに、文章の意図を読み取る国語でつまずく受験生、あの得意不得意。", "terms": [["東ロボくん", "大学入試突破を目標にした日本のAIプロジェクト。文章の意味理解の限界を示した"], ["意味理解", "文章が指す本当の意味を捉えること。AIには依然として難しい課題"]], "think": "「大学入試・日本・読解の限界」なら東ロボくん。囲碁のAlphaGoやクイズのWatsonとは、扱う課題が違う。", "vs": "AlphaGoは囲碁のAI、Watsonはクイズの質問応答システム、ELIZAはおうむ返しの対話プログラムで、いずれも大学入試に挑んだ東ロボくんではない。", "usecase": "「AIは計算は得意でも意味理解は苦手」という限界を示す代表例。AIに何を任せ、何を任せにくいかを考える材料になる。", "opt": ["正解。大学入試突破を目指し読解の限界を示した日本のプロジェクトが東ロボくん。", "囲碁で人に勝ったAIで、大学入試のプロジェクトではない。", "クイズの質問応答システムで、大学入試に挑んだものではない。", "おうむ返しの対話プログラムで、東ロボくんではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-d' AND c.name='2. 人工知能をめぐる動向'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-d-q7', '1958年に考案された、脳の神経細胞をまねて入力に重みを掛けて足し合わせ、しきい値で出力を決める、ニューラルネットワークの起源となったモデルはどれか。', NULL, '["パーセプトロン", "サポートベクターマシン", "決定木", "ランダムフォレスト"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "脳の神経細胞をまねた、ニューラルネットワークの起源となった1958年のモデルは？", "point": "「入力に重みを掛けて足し、しきい値で出力を決める、ニューラルネットの起源」なら、パーセプトロン。", "kid": "脳の神経細胞をまねて、入力に重み(効き具合)を掛けて足し合わせ、その合計がしきい値を超えたら反応する、という最初期のモデル。今のニューラルネットワークの出発点。", "eg": "複数の情報に「重要度」を付けて足し算し、合計がある基準を超えたら「YES」と判断する、あのシンプルな決め方。", "terms": [["パーセプトロン", "入力に重みを掛けて足し、しきい値で出力を決めるモデル。ニューラルネットワークの起源"], ["多層パーセプトロン", "隠れ層を加えてXORなど複雑な問題も解けるようにした発展形"]], "think": "「重み付き和＋しきい値・ニューラルネットの起源・1958年」ならパーセプトロン。データを2分する境界を学ぶSVMなど後の手法とは別。", "vs": "サポートベクターマシンは余白を最大化して分ける後発の手法、決定木は条件分岐で予測する手法、ランダムフォレストは決定木を束ねる手法で、いずれもニューラルネットの起源パーセプトロンではない。", "usecase": "ニューラルネットワーク、ひいてはディープラーニングの原点。ここから層を深くする流れが今のAIにつながっている。", "opt": ["正解。重み付き和としきい値で出力を決める、ニューラルネットの起源がパーセプトロン。", "余白を最大化して分ける後発の分類手法で、起源のモデルではない。", "条件分岐で予測する手法で、パーセプトロンではない。", "決定木を束ねる手法で、ニューラルネットの起源ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-d' AND c.name='2. 人工知能をめぐる動向'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-d-q8', '単純な計算を大量に同時並行でこなすのが得意で、ディープラーニングの学習を高速化し、その普及を支えた演算装置はどれか。', NULL, '["GPU", "SSD", "RAM", "ルーター"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "単純計算を大量に並列でこなし、ディープラーニングの学習を高速化した装置は？", "point": "「単純計算を大量に並列でこなし、DLの学習を高速化した装置」なら、GPU。", "kid": "ディープラーニングは、同じような掛け算・足し算を膨大に繰り返す。GPUはその単純計算を一度に大量にこなすのが得意で、学習を大幅に速くした。だからディープラーニングが実用になった。", "eg": "一人の天才(CPU)が難問を順に解くより、大勢のアルバイト(GPU)が単純作業を一斉に片付ける方が速い、あの分業。", "terms": [["GPU", "単純な計算を大量に同時並行でこなす演算装置。ディープラーニングの学習を高速化した"], ["CPU", "複雑な処理を順にこなす汎用の演算装置。並列の単純計算はGPUが得意"]], "think": "「単純計算を大量に並列・DLを高速化」ならGPU。データを保存するSSDや、作業用メモリのRAMとは役割が違う。", "vs": "SSDはデータを保存する記憶装置、RAMは作業用の一時メモリ、ルーターはネットワークを中継する機器で、いずれも並列計算でDLを速くするGPUではない。", "usecase": "ビッグデータと並ぶ、ディープラーニング普及の立役者。大規模モデルの学習にはGPU(やその発展形)が欠かせない。", "opt": ["正解。単純計算を大量に並列でこなしDLを高速化したのがGPU。", "データを保存する記憶装置で、計算を速くする装置ではない。", "作業用の一時メモリで、並列計算の装置ではない。", "ネットワークを中継する機器で、計算装置ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-d' AND c.name='2. 人工知能をめぐる動向'
