INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-d-q9', 'インターネットの普及などで大量・多様なデータが集まるようになったことは、ディープラーニング普及の大きな一因とされる。この大量のデータを指す語はどれか。', NULL, '["ビッグデータ", "オープンデータ", "メタデータ", "データリーケージ"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "大量・多様に集まるようになり、DL普及を支えたデータを指す語は？", "point": "「大量・多様に集まった、DL普及を支えたデータ」なら、ビッグデータ。", "kid": "ディープラーニングは、たくさんのデータで学ぶほど賢くなる。インターネットやスマホの普及で大量・多様なデータが集まるようになったことが、ディープラーニングが花開いた一因。この大量のデータがビッグデータ。", "eg": "大量の練習問題が手に入ったから、たくさん解いて実力を伸ばせた、あの環境の変化。", "terms": [["ビッグデータ", "量・種類・発生速度の大きい、大量で多様なデータ。ディープラーニング普及の一因"], ["GPU", "大量の計算を並列でこなす装置。ビッグデータと並ぶDL普及の立役者"]], "think": "「大量・多様なデータ・DL普及の一因」ならビッグデータ。自由に使える公開データのオープンデータとは、指すものが違う。", "vs": "オープンデータは誰でも自由に使える公開データ、メタデータはデータの説明情報、データリーケージは答えが訓練に漏れる問題で、いずれも大量・多様なデータを指すビッグデータではない。", "usecase": "「なぜ2010年代にディープラーニングが実用化したか」の答えの一つ。GPU(計算力)とビッグデータ(データ量)がそろったことが大きい。", "opt": ["正解。大量・多様に集まったデータで、DL普及を支えたのがビッグデータ。", "誰でも自由に使える公開データで、量の大きさを指す語ではない。", "データの説明情報で、大量のデータそのものではない。", "答えが訓練に漏れる問題で、データの種類ではない。"]}'::jsonb, 1
