INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-d-q10', '第1次AIブームで中心となった、問題をルールに従って場合分けし、ゴールへの道筋を筋道立てて探し出す取り組みを指す語はどれか。', NULL, '["推論と探索", "機械学習", "ディープラーニング", "知識の蒸留"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "第1次ブームの中心だった、場合分けしてゴールへの道筋を探す取り組みは？", "point": "「問題を場合分けして、ゴールへの道筋を筋道立てて探す(第1次ブームの中心)」なら、推論と探索。", "kid": "第1次AIブームでは、迷路やパズルのように、ルールに従って場合分けし、ゴールまでの道筋を一つずつ探し出す方法が中心だった。この筋道立てて答えを探す取り組みが推論と探索。", "eg": "迷路で分かれ道を一つずつ試し、行き止まりなら戻ってゴールまでの道を探す、あの探し方。", "terms": [["推論と探索", "ルールに従って場合分けし、ゴールへの道筋を探し出す取り組み。第1次AIブームの中心"], ["トイ・プロブレム", "単純化された問題。推論と探索は現実の複雑な問題には歯が立たなかった"]], "think": "「場合分けして道筋を探す・第1次ブーム」なら推論と探索。データから学ぶ機械学習(第3次ブーム中心)とは時代も発想も違う。", "vs": "機械学習はデータから学ぶ手法、ディープラーニングは特徴まで学ぶ手法、知識の蒸留はモデルを軽くする手法で、いずれも第1次ブームの推論と探索ではない。", "usecase": "AIの歴史の最初の柱。単純な問題は解けても現実の複雑さに届かなかった限界(トイ・プロブレム)が、次の時代への課題になった。", "opt": ["正解。場合分けして道筋を探す第1次ブームの取り組みが推論と探索。", "データから学ぶ手法で、第1次ブームの推論と探索ではない。", "特徴まで学ぶ手法で、第1次ブームの取り組みではない。", "モデルを軽くする手法で、推論と探索とは別。"]}'::jsonb, 1
