INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-d-q12', '学習の段階ではデータを覚えておくだけで、予測するときに「近くにある学習データ」を見て多数決する、怠惰学習とも呼ばれる手法はどれか。', NULL, '["k近傍法（k-NN）", "ロジスティック回帰", "サポートベクターマシン", "オートエンコーダ"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "予測時に近くの学習データを見て多数決する、怠惰学習とも呼ばれる手法は？", "point": "「学習時は覚えるだけ、予測時に近くのデータを多数決する」なら、k近傍法(k-NN)。", "kid": "ふつうの手法は学習でモデルを作り込む。k近傍法は学習時はデータを覚えておくだけで、予測するときに「近くにある学習データ」を見て多数決する。予測時まで判断を先送りするので怠惰学習と呼ばれる。", "eg": "引っ越し先で自分の好みが分からないとき、ご近所さんの多数派に合わせて決める、あの決め方。", "terms": [["k近傍法（k-NN）", "予測時に近くのk個の学習データの多数決で分類する手法。怠惰学習とも呼ばれる"], ["怠惰学習", "学習時にはモデルを作らず、予測時に計算する方式。k-NNが代表"]], "think": "「学習時は覚えるだけ・予測時に近くを多数決」ならk近傍法。学習でモデルを作り込むロジスティック回帰やSVMとは、判断のタイミングが違う。", "vs": "ロジスティック回帰は学習で境界を作り込む、サポートベクターマシンも学習で境界を作る、オートエンコーダは圧縮・復元を学ぶ構造で、いずれも予測時に多数決するk近傍法ではない。", "usecase": "少数のデータで手早く分類したいときや、基準となる簡単な手法として使う。データが増えると予測が重くなる点が弱み。", "opt": ["正解。予測時に近くのデータを多数決するのがk近傍法。", "学習で境界を作り込む手法で、予測時に多数決するのとは違う。", "学習で境界を作る手法で、怠惰学習ではない。", "圧縮・復元を学ぶ構造で、多数決の分類ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-d' AND c.name='3. 機械学習の概要'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-d-q13', '「赤・青・緑」のような、大小関係のないカテゴリの項目を、機械学習で扱えるよう、各カテゴリに対応する1か所だけを1にしたベクトルへ変換する方法はどれか。', NULL, '["ワンホットエンコーディング", "ラベルエンコーディング", "ミニマックス正規化", "ブートストラップ法"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "大小関係のないカテゴリを、1か所だけ1のベクトルに変換する方法は？", "point": "「カテゴリを、各値に対応する1か所だけ1のベクトルにする」なら、ワンホットエンコーディング。", "kid": "「赤・青・緑」を1・2・3という数字にすると、機械が「緑は赤の3倍」と勝手に大小をつけてしまう。そこで「赤＝(1,0,0)」のように、対応する1か所だけを1にしたベクトルにして、順序の誤解を防ぐ。これがワンホットエンコーディング。", "eg": "出席簿のチェック欄のように、「あてはまる欄だけにチェック(1)、他は空欄(0)」で表す、あの方式。", "terms": [["ワンホットエンコーディング", "大小関係のないカテゴリを、対応する1か所だけ1にしたベクトルへ変換する方法"], ["ラベルエンコーディング", "カテゴリを整数に置き換える方法。順序があると誤解される場合があり注意"]], "think": "「カテゴリを1か所だけ1のベクトルに・順序の誤解を防ぐ」ならワンホットエンコーディング。桁をそろえる標準化とは目的が違う前処理。", "vs": "ラベルエンコーディングはカテゴリを整数に置き換える(順序の誤解が起きうる)、ミニマックス正規化は数値を0〜1に収める、ブートストラップ法は重複ありでデータを選び直す方法で、いずれもワンホットエンコーディングではない。", "usecase": "色・地域・種別などカテゴリの項目を機械学習に入れる前の定番の前処理。順序の無い項目に不要な大小関係を持ち込まないために使う。", "opt": ["正解。カテゴリを1か所だけ1のベクトルにするのがワンホットエンコーディング。", "カテゴリを整数に置き換える方法で、順序の誤解が起きうる別の方法。", "数値を0〜1に収める正規化で、カテゴリのベクトル化ではない。", "重複ありでデータを選び直す方法で、カテゴリの変換ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-d' AND c.name='3. 機械学習の概要'
