INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-d-q14', 'データに含まれる、値が抜けている箇所（欠損値）を、平均値や中央値などで埋めて分析や学習に使えるようにする処理はどれか。', NULL, '["欠損値の補完", "データ拡張", "次元削減", "アノテーション"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "抜けている値を平均値などで埋めて、使えるようにする処理は？", "point": "「抜けている値(欠損値)を平均などで埋める」なら、欠損値の補完。", "kid": "集めたデータには、記入漏れなどで値が抜けている箇所(欠損値)がある。多くの手法は欠損があると動かないので、平均値や中央値などで埋めて使えるようにする。この穴埋めが欠損値の補完。", "eg": "アンケートの空欄を、全体の平均的な回答で埋めて集計に使えるようにする、あの穴埋め。", "terms": [["欠損値の補完", "抜けている値(欠損値)を、平均値・中央値などで埋めて使えるようにする処理"], ["欠損値", "本来あるべき値が抜けている箇所。埋めるか、その行を除くかを判断する"]], "think": "「抜けた値を埋める」なら欠損値の補完。データを増やすデータ拡張や、項目を減らす次元削減とは目的が違う前処理。", "vs": "データ拡張はデータを水増しする手法、次元削減は項目の数を減らす手法、アノテーションは正解ラベルを付ける作業で、いずれも欠損値を埋める補完ではない。", "usecase": "現実のデータには欠損がつきもの。埋め方(平均・中央値・別の値の予測など)を選ぶことが、分析や学習の質を左右する下ごしらえ。", "opt": ["正解。抜けている値を平均などで埋めるのが欠損値の補完。", "データを水増しする手法で、欠損を埋める処理ではない。", "項目の数を減らす手法で、欠損の穴埋めではない。", "正解ラベルを付ける作業で、欠損値の補完ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-d' AND c.name='3. 機械学習の概要'
