INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-d-q15', '陽性がごくわずかしかない偏ったデータで、少数派のデータを水増しして数のバランスを整える対処はどれか。', NULL, '["オーバーサンプリング", "アンダーサンプリング", "標準化", "正則化"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "少数派を水増しして偏りを整える対処は？", "point": "「少数派を水増しして数のバランスを整える」なら、オーバーサンプリング。", "kid": "陽性1%のような偏ったデータをそのまま学ぶと、AIは「全部陰性」と答えるだけで済んでしまう。そこで少数派(陽性)を水増しして数のバランスを整えるのがオーバーサンプリング。逆に多数派を減らすのがアンダーサンプリング。", "eg": "少人数の意見が埋もれないよう、その分のコピーを増やして多数派と釣り合わせる、あの調整。", "terms": [["オーバーサンプリング", "少数派のデータを水増しして、多数派との数のバランスを整える対処"], ["アンダーサンプリング", "多数派のデータを減らして、少数派との数のバランスを整える対処"]], "think": "「少数派を増やす」ならオーバーサンプリング、「多数派を減らす」ならアンダーサンプリング。どちらも不均衡データの偏りを整える対処。", "vs": "アンダーサンプリングは多数派を減らす逆の対処、標準化は数値の桁をそろえる前処理、正則化は過学習を抑える手法で、いずれも少数派を水増しするオーバーサンプリングではない。", "usecase": "不正検知や病気の検査など、陽性がまれで偏ったデータの学習で使う。偏りを整えて、少数派をちゃんと拾えるモデルにする。", "opt": ["正解。少数派を水増しして数のバランスを整えるのがオーバーサンプリング。", "多数派を減らす逆の対処で、少数派を増やすものではない。", "数値の桁をそろえる前処理で、数のバランス調整ではない。", "過学習を抑える手法で、不均衡データの対処そのものではない。"]}'::jsonb, 1
