SELECT s.id, c.id, 'g-kentei-d-q17', 'モデルが単純すぎて、訓練データにすら十分に当てはめられず、訓練でも本番でも精度が低い状態はどれか。', NULL, '["未学習", "過学習", "データリーケージ", "勾配消失"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "モデルが単純すぎて訓練でも本番でも精度が低い状態は？", "point": "「モデルが単純すぎて、訓練データにすら当てはまらない」なら、未学習。", "kid": "モデルが単純すぎると、訓練データのパターンすら捉えられず、訓練でも本番でも成績が悪い。この“当てはめ不足”が未学習(アンダーフィッティング)。逆に、訓練だけできて本番でダメなのが過学習。", "eg": "練習問題すらろくに解けない“準備不足”の状態、あの手応えのなさ。", "terms": [["未学習（アンダーフィッティング）", "モデルが単純すぎて、訓練データにすら十分当てはまらない状態"], ["過学習", "訓練データに合わせすぎて、初見で精度が落ちる逆の状態"]], "think": "「訓練でもダメ」なら未学習、「訓練は良いが本番でダメ」なら過学習。訓練の成績で見分ける。未学習はモデルを複雑にする・特徴を増やすなどで改善する。", "vs": "過学習は訓練だけできて本番で落ちる逆の状態、データリーケージは答えが漏れて過大評価される問題、勾配消失は学習の信号が消える問題で、いずれも当てはめ不足の未学習ではない。", "usecase": "訓練の成績も伸びないときに疑う。モデルを複雑にする、特徴量を増やす、学習を長くするなどで改善を図る、という診断の入り口。", "opt": ["正解。単純すぎて訓練データにすら当てはまらないのが未学習。", "訓練は良いが本番で落ちる逆の状態で、当てはめ不足ではない。", "答えが漏れて評価が過大になる問題で、当てはめ不足ではない。", "学習の信号が消える問題で、未学習とは別。"]}'::jsonb, 1
