SELECT s.id, c.id, 'g-kentei-d-q19', '入力を-1から+1の範囲に変換する活性化関数で、出力の中心が0になるためシグモイドより扱いやすいとされるものはどれか。', NULL, '["tanh関数", "ソフトマックス関数", "交差エントロピー", "平均二乗誤差"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "入力を-1〜+1に変換し、中心が0で扱いやすい活性化関数は？", "point": "「入力を-1〜+1に変換し、中心が0」なら、tanh関数。", "kid": "入力を-1〜+1の範囲に変換する活性化関数。出力の中心が0(プラスにもマイナスにも振れる)なので、0〜1に偏るシグモイドより学習が進みやすいとされる。中間層で使われる。", "eg": "温度計のように、0を中心にプラス側・マイナス側の両方へ振れる目盛りに変換する、あのイメージ。", "terms": [["tanh関数", "入力を-1〜+1に変換する活性化関数。出力の中心が0で、シグモイドより扱いやすいとされる"], ["シグモイド関数", "入力を0〜1に押し込む関数。出力が0寄りに偏る"]], "think": "「-1〜+1・中心が0の活性化関数」ならtanh。0〜1に押し込むシグモイドと、範囲と中心が違う。", "vs": "ソフトマックスは多クラスを確率にする出力関数、交差エントロピーと平均二乗誤差は誤差を測る損失関数で、いずれも-1〜+1に変換する活性化関数tanhではない。", "usecase": "ニューラルネットの中間層の活性化関数として使う。出力が0を中心に振れるため学習が偏りにくいのが利点(今はReLUも広く使われる)。", "opt": ["正解。入力を-1〜+1に変換し中心が0なのがtanh。", "多クラスを確率にする出力関数で、活性化のtanhではない。", "誤差を測る損失関数で、活性化関数ではない。", "回帰の誤差を測る損失関数で、活性化関数ではない。"]}'::jsonb, 1
