INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-d-q20', '学習を始めるときに各重みへ与える最初の値の決め方で、これが不適切だと勾配消失などで学習が進みにくくなるものはどれか。', NULL, '["重みの初期化", "データ拡張", "早期終了", "アノテーション"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "学習開始時に各重みへ与える最初の値の決め方は？", "point": "「学習開始時に各重みへ与える最初の値の決め方」なら、重みの初期化。", "kid": "学習は各重み(効き具合)を少しずつ直していくが、その“スタート地点”の値を決めるのが重みの初期化。全部同じ値や大きすぎ・小さすぎだと、勾配が消えたりして学習が進まない。だから適切に散らして初期化する。", "eg": "山下りのスタート地点。変な場所から始めると谷底にたどり着きにくいので、良い出発点を選んでおく、あの準備。", "terms": [["重みの初期化", "学習開始時に各重みへ与える最初の値の決め方。不適切だと学習が進みにくい"], ["Xavier初期化／He初期化", "勾配消失などを避けるためによく使われる、代表的な重み初期化の方法"]], "think": "「学習開始時の重みの最初の値の決め方」なら重みの初期化。データを増やすデータ拡張や、学習を止める早期終了とは役割が違う。", "vs": "データ拡張はデータの水増し、早期終了は学習を途中で止める手法、アノテーションは正解ラベル付けで、いずれも学習開始時の重みの決め方(初期化)ではない。", "usecase": "深いネットワークが最初からうまく学習できるかを左右する。XavierやHeといった、活性化関数に合った初期化を選ぶのが定石。", "opt": ["正解。学習開始時に各重みへ与える最初の値の決め方が重みの初期化。", "データの水増しで、重みの初期値の決め方ではない。", "学習を途中で止める手法で、初期化ではない。", "正解ラベルを付ける作業で、重みの初期化ではない。"]}'::jsonb, 1
