SELECT s.id, c.id, 'g-kentei-d-q29', '画像認識で使う畳み込みニューラルネットワーク（CNN）の典型的な構成として、最も適切なものはどれか。', NULL, '["畳み込みとプーリングで特徴を抽出し、全結合層で分類する", "全結合層だけを何層も積み重ねて画像を処理する構成", "系列を前から1時点ずつ処理する回帰結合層だけで構成する", "入力をそのまま出力するだけの層を並べた構成"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "画像認識で使うCNNの典型的な構成は？", "point": "「畳み込みとプーリングで特徴を抽出→全結合層で分類」なら、CNNの典型構成。", "kid": "CNNは、畳み込み層(線や角などの特徴を拾う)とプーリング層(縮めて位置ずれに強くする)を交互に重ねて特徴を抽出し、最後に全結合層でまとめて「何の画像か」を分類する。この流れが基本。", "eg": "まず素材の特徴を下ごしらえ(畳み込み・プーリング)して、最後に全部を合わせて味を決める(全結合層で判定)、あの調理の流れ。", "terms": [["CNN（畳み込みニューラルネットワーク）", "畳み込み層・プーリング層で特徴を抽出し、全結合層で分類する、画像認識向けのネットワーク"], ["畳み込み層／プーリング層", "特徴を拾う層と、縮めて位置ずれに強くする層"]], "think": "「畳み込み＋プーリングで特徴抽出→全結合で分類」がCNNの基本構成。全結合だけ・回帰結合だけ、では画像の特徴をうまく拾えない。", "vs": "全結合層だけでは局所特徴を効率よく拾えず、回帰結合層だけは系列向けで画像には不向き、入力をそのまま出す層だけでは何も学べず、いずれもCNNの典型構成ではない。", "usecase": "画像分類・物体検出・顔認証など、画像を扱うAIの基本形。この構成を土台に、より深い・工夫された構造へ発展した。", "opt": ["正解。畳み込みとプーリングで特徴を抽出し、全結合層で分類するのがCNN。", "全結合層だけでは局所特徴を効率よく拾えず、画像向けの構成ではない。", "回帰結合層は系列向けで、画像認識の典型構成ではない。", "入力をそのまま出すだけでは何も学べず、CNNではない。"]}'::jsonb, 1
