SELECT s.id, c.id, 'g-kentei-d-q30', '低い解像度のぼやけた画像から、細部を補って高い解像度の鮮明な画像を作り出すタスクはどれか。', NULL, '["超解像", "画像分類", "異常検知", "感情分析"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "低解像度のぼやけた画像を、高解像度の鮮明な画像にするタスクは？", "point": "「ぼやけた低解像度画像を、鮮明な高解像度画像にする」なら、超解像。", "kid": "ぼやけて粗い画像から、失われた細部を推測して補い、くっきりした高解像度の画像を作り出すタスク。古い写真の高画質化などに使う。", "eg": "粗い証明写真を、細部を補ってくっきり引き伸ばす、あの高画質化。", "terms": [["超解像", "低解像度の画像から細部を補い、高解像度の鮮明な画像を作り出すタスク"], ["転置畳み込み", "小さな特徴を引き伸ばす操作。超解像の中で使われることがある"]], "think": "「ぼやけを鮮明に高解像度化」なら超解像。写真全体に1ラベルの画像分類や、外れ値を見つける異常検知とは目的が違う。", "vs": "画像分類は写真全体に1ラベルを付ける、異常検知は普段と違うものを見つける、感情分析は文章の気持ちを判定するタスクで、いずれも画像を高解像度化する超解像ではない。", "usecase": "古い写真や監視カメラ映像の高画質化、医療画像の鮮明化などで使う。細部を推測して補うので、無い情報を作る点には注意。", "opt": ["正解。低解像度の画像を高解像度の鮮明な画像にするのが超解像。", "写真全体に1ラベルを付けるタスクで、高解像度化ではない。", "普段と違うものを見つけるタスクで、超解像ではない。", "文章の気持ちを判定するタスクで、画像の高解像度化ではない。"]}'::jsonb, 1
