SELECT s.id, c.id, 'g-kentei-d-q35', '印刷物や手書きの画像の中に写っている文字を読み取り、編集できるテキストデータに変換する技術はどれか。', NULL, '["OCR", "音声認識", "画像生成", "感情分析"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "画像中の文字を読み取って、編集できるテキストにする技術は？", "point": "「画像の中の文字を読み取ってテキストにする」なら、OCR。", "kid": "紙の書類や看板の写真に写っている文字を、機械が読み取って、コピーや検索ができるテキストデータに変換する技術。スキャンした書類の文字起こしなどに使う。", "eg": "紙の資料をスマホで撮ると、中の文字を読み取ってそのままコピーできる、あの機能。", "terms": [["OCR（光学的文字認識）", "画像中の文字を読み取り、編集できるテキストデータに変換する技術"], ["音声認識", "音声を文字にする別のタスク。OCRは画像から文字を読み取る"]], "think": "「画像の中の文字を読み取ってテキストに」ならOCR。声を文字にする音声認識とは、入力が画像か音声かで違う。", "vs": "音声認識は声を文字にする、画像生成は画像を作る、感情分析は文章の気持ちを判定するタスクで、いずれも画像中の文字を読み取るOCRではない。", "usecase": "紙の書類の電子化、名刺や領収書の読み取り、車のナンバー認識などで使う。大量の紙情報をデータ化するのに役立つ。", "opt": ["正解。画像中の文字を読み取ってテキストにするのがOCR。", "声を文字にするタスクで、画像中の文字を読むものではない。", "画像を作るタスクで、文字の読み取りではない。", "文章の気持ちを判定するタスクで、OCRではない。"]}'::jsonb, 1
