SELECT s.id, c.id, 'g-kentei-d-q36', '「夕焼けの海辺を走る犬」のような文章による指示から、その内容に合った画像を新しく作り出すタスクはどれか。', NULL, '["テキストからの画像生成", "画像からの説明文生成", "画像のスタイル変換", "画像の高解像度化"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "文章の指示から、その内容に合った画像を新しく作るタスクは？", "point": "「文章の指示から、内容に合った画像を新しく作る」なら、テキストからの画像生成。", "kid": "「夕焼けの海辺を走る犬」のような文章を入れると、その内容の画像を新しく描き起こすタスク。文章(テキスト)→画像の向き。Stable DiffusionやDALL-Eが代表。", "eg": "注文(文章)を伝えると、その通りの絵を描いてくれる絵描きさん、あのイメージ。", "terms": [["テキストからの画像生成", "文章の指示から、その内容に合った画像を新しく生成するタスク。text-to-image"], ["拡散モデル", "ノイズを取り除いて画像を作る手法。テキストからの画像生成の主流"]], "think": "「文章から画像を新しく作る」ならテキストからの画像生成。逆の「画像から説明文」は画像キャプション生成で、向きが逆。", "vs": "画像からの説明文生成は画像から文章で向きが逆、スタイル変換は画風だけ変える、高解像度化は鮮明にするタスクで、いずれも文章から画像を作るテキストからの画像生成ではない。", "usecase": "イラスト・デザイン・広告素材の制作などで使う、今の生成AIの代表的な応用。拡散モデルの発展で急速に実用化した。", "opt": ["正解。文章の指示から内容に合った画像を新しく作るのがテキストからの画像生成。", "画像から説明文を作るタスクで、向きが逆。", "画風だけを変えるタスクで、新しく作るのとは違う。", "画像を鮮明にするタスクで、文章からの生成ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-d' AND c.name='6. ディープラーニングの応用例'
