INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-d-q38', 'AIにすべてを任せきりにせず、重要な判断には人間が関与・確認して、AIと人が協力して進める仕組みはどれか。', NULL, '["ヒューマン・イン・ザ・ループ", "エンドツーエンド学習", "フルオートメーション", "バッチ処理"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "重要な判断に人間が関与・確認して、AIと人が協力して進める仕組みは？", "point": "「重要な判断に人が関与・確認し、AIと人が協力する」なら、ヒューマン・イン・ザ・ループ。", "kid": "AIに全部任せると、間違いをそのまま実行してしまう危険がある。そこで大事な判断には人間が入って確認・修正し、AIと人が協力して進める。この人が関わる仕組みがヒューマン・イン・ザ・ループ。", "eg": "自動運転でも最終的にドライバーが確認・介入できるようにしておく、あの“人が最後の砦”の考え方。", "terms": [["ヒューマン・イン・ザ・ループ", "重要な判断に人間が関与・確認し、AIと人が協力して進める仕組み"], ["自動化のトレードオフ", "全自動は速いが誤りを止めにくい。人が関わると安全だが手間が増える"]], "think": "「重要な判断に人が関与・AIと協力」ならヒューマン・イン・ザ・ループ。人を挟まず全自動にするフルオートメーションとは考え方が逆。", "vs": "エンドツーエンド学習は入力から出力まで一気に学ぶ手法、フルオートメーションは人を挟まない全自動、バッチ処理はまとめて一括処理する方式で、いずれも人が関与するヒューマン・イン・ザ・ループではない。", "usecase": "医療診断・与信・採用など、誤りが重大な場面で使う。AIが候補を出し、最終判断は人が行うことで、精度と責任のバランスを取る。", "opt": ["正解。重要な判断に人が関与しAIと協力するのがヒューマン・イン・ザ・ループ。", "入力から出力まで一気に学ぶ手法で、人の関与の仕組みではない。", "人を挟まない全自動で、人が関与する考え方とは逆。", "まとめて一括処理する方式で、人の関与の仕組みではない。"]}'::jsonb, 1
