INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-d-q39', '学習済みのモデルに新しいデータを入れて、実際に予測や判断の結果を出す段階を指す語はどれか。', NULL, '["推論", "学習", "アノテーション", "デプロイ"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "学習済みモデルに新しいデータを入れて、予測結果を出す段階は？", "point": "「学習済みモデルを使って、実際に予測結果を出す段階」なら、推論。", "kid": "モデル作りには2つの段階がある。データからパターンを覚える「学習」と、覚えたモデルに新しいデータを入れて実際に答えを出す「推論」。運用中に毎回行うのは推論の方。", "eg": "教科書で勉強するのが学習、本番の試験で問題に答えるのが推論、あの区別。", "terms": [["推論（インファレンス）", "学習済みモデルに新しいデータを入れ、予測や判断の結果を出す段階"], ["学習（トレーニング）", "データからパターンを学び、モデルを作る段階。推論の前段"]], "think": "「学習済みモデルで実際に答えを出す」なら推論。データから覚える学習とは、段階が違う。運用で繰り返すのは推論。", "vs": "学習はモデルを作る段階、アノテーションは正解ラベルを付ける作業、デプロイはモデルを本番に配置することで、いずれも予測結果を出す推論そのものではない。", "usecase": "運用中のAIが毎回行う処理。推論を速く・安く行えるかが、実用サービスの応答速度やコストを左右する(だからモデルの軽量化が重要)。", "opt": ["正解。学習済みモデルで実際に予測結果を出す段階が推論。", "データからパターンを学びモデルを作る段階で、結果を出す推論ではない。", "正解ラベルを付ける作業で、推論ではない。", "モデルを本番に配置することで、予測を出す推論そのものではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-d' AND c.name='7. AIの社会実装に向けて'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-d-q40', '回帰モデルの評価で、予測値と正解値の差を二乗して平均した、値が小さいほど良い誤差指標はどれか。', NULL, '["平均二乗誤差", "混同行列", "ROC曲線とAUC", "交差エントロピー誤差"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "回帰で、予測と正解の差を二乗して平均した、小さいほど良い誤差指標は？", "point": "「回帰で、予測と正解の差を二乗して平均した誤差」なら、平均二乗誤差(MSE)。", "kid": "回帰(数値予測)の成績を測るとき、予測と正解のズレを二乗して平均する。二乗するので大きな外れを重く見る。値が小さいほど良い。これが平均二乗誤差。", "eg": "射的で、的の中心からの外れ具合を二乗して平均し、外れが大きいほど大きく減点する、あの採点。", "terms": [["平均二乗誤差（MSE）", "予測と正解の差を二乗して平均した、回帰の誤差指標。小さいほど良い"], ["決定係数（R²）", "回帰モデルがデータの動きをどれだけ説明できるかを表す指標。1に近いほど良い"]], "think": "「回帰・差を二乗して平均・小さいほど良い」なら平均二乗誤差。分類の成績を測る正解率や適合率とは、対象(数値予測か分類か)が違う。", "vs": "混同行列は分類結果の集計表、ROC曲線とAUCは分類の性能曲線、交差エントロピー誤差は分類の損失で、いずれも回帰の誤差を測る平均二乗誤差ではない。", "usecase": "売上や価格などの数値予測モデルの評価・学習の目印に使う。大きな外れを重く見るので、外れ値に敏感な点に注意。", "opt": ["正解。予測と正解の差を二乗して平均した回帰の誤差が平均二乗誤差。", "分類結果の集計表で、回帰の誤差指標ではない。", "分類の性能曲線と面積で、回帰の誤差ではない。", "分類の損失で、回帰の誤差そのものではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-d' AND c.name='8. AIに必要な数理・統計知識'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-d-q41', '回帰モデルが、データの動き（ばらつき）をどれくらいうまく説明できているかを、1に近いほど良いとして表す指標はどれか。', NULL, '["決定係数", "再現率", "混同行列", "標準偏差"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "回帰モデルがデータの動きをどれだけ説明できるかを1に近いほど良いと表す指標は？", "point": "「回帰で、データの動きをどれだけ説明できるかを1に近いほど良いと表す」なら、決定係数(R²)。", "kid": "回帰モデルが、データのばらつき(動き)をどれくらい言い当てられているかを表す指標。1に近いほど「よく説明できている」、0に近いと「ほとんど説明できていない」。", "eg": "テストの点のばらつきを、勉強時間でどれだけ説明できるか。ぴったり説明できれば1に近い、あの当てはまり具合。", "terms": [["決定係数（R²）", "回帰モデルがデータの動き(ばらつき)をどれだけ説明できるかを表す指標。1に近いほど良い"], ["平均二乗誤差（MSE）", "予測と正解の差を二乗して平均した誤差。小さいほど良い"]], "think": "「回帰・当てはまりの良さ・1に近いほど良い」なら決定係数。誤差の大きさを測る平均二乗誤差とは、見る角度が違う(説明力か、ズレの大きさか)。", "vs": "再現率は分類で見落としの少なさを表す指標、混同行列は分類結果の集計表、標準偏差はデータの散らばりの大きさで、いずれも回帰の説明力を表す決定係数ではない。", "usecase": "回帰モデルの「当てはまりの良さ」を一目で伝えるのに使う。ただし項目を増やすと見かけ上上がりやすい点には注意が要る。", "opt": ["正解。回帰の当てはまりの良さを1に近いほど良いと表すのが決定係数。", "分類で見落としの少なさを表す指標で、回帰の説明力ではない。", "分類結果の集計表で、決定係数ではない。", "データの散らばりの大きさで、当てはまりの良さではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-d' AND c.name='8. AIに必要な数理・統計知識'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-d-q42', '2つのベクトルが「同じ向きをどれだけ向いているか」で、文書や単語の似ている度合いを測る指標はどれか。', NULL, '["コサイン類似度", "平均二乗誤差", "混同行列", "学習率"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "2つのベクトルの向きの近さで、文書や単語の似ている度合いを測る指標は？", "point": "「2つのベクトルの向きの近さで似ている度合いを測る」なら、コサイン類似度。", "kid": "文書や単語を数値のベクトルにしたとき、その2つが「同じ向きを向いているか」で似ている度合いを測る。向きがそろうほど1に近く(似ている)、直角なら0(無関係)。長さより向きを重視する。", "eg": "2本の矢印が同じ方向を指していれば「似ている」、直角なら「無関係」と判断する、あの向きの比べ方。", "terms": [["コサイン類似度", "2つのベクトルのなす角度(向きの近さ)で、似ている度合いを測る指標。1に近いほど似ている"], ["分散表現", "単語などを意味を反映したベクトルにしたもの。コサイン類似度で近さを測れる"]], "think": "「ベクトルの向きの近さで類似度」ならコサイン類似度。誤差を測る平均二乗誤差や、分類の集計表の混同行列とは目的が違う。", "vs": "平均二乗誤差は回帰の誤差指標、混同行列は分類結果の集計表、学習率は更新の歩幅で、いずれもベクトルの向きの近さを測るコサイン類似度ではない。", "usecase": "検索・レコメンド・文書分類で、単語や文書の似ている度合いを測るのに使う。長さの影響を受けにくいのが利点。", "opt": ["正解。2つのベクトルの向きの近さで似ている度合いを測るのがコサイン類似度。", "回帰の誤差指標で、ベクトルの向きの近さではない。", "分類結果の集計表で、類似度の指標ではない。", "更新の歩幅を決める値で、類似度ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-d' AND c.name='8. AIに必要な数理・統計知識'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-d-q43', '起こりうる結果の値それぞれに、その起こりやすさ（確率）で重みをつけて足し合わせた、平均的に見込まれる値を指す語はどれか。', NULL, '["期待値", "中央値", "標準偏差", "最頻値"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "起こりうる値に確率で重みをつけて足した、平均的に見込まれる値は？", "point": "「起こりうる値に確率で重みをつけて足した、平均的に見込まれる値」なら、期待値。", "kid": "サイコロで出る目は1〜6。それぞれ1/6の確率で起きる。値×確率を全部足すと「平均的にどれくらいの値が見込めるか」が分かる。これが期待値。ギャンブルの損得計算などに使う。", "eg": "宝くじの「1枚あたり平均でいくら戻ってくるか」を、当選金×当たる確率を足して見積もる、あの計算。", "terms": [["期待値", "起こりうる値に、その確率で重みをつけて足し合わせた、平均的に見込まれる値"], ["確率", "ある結果の起こりやすさ。期待値の重みになる"]], "think": "「値×確率を足した平均的な見込み」なら期待値。データを並べた真ん中の中央値や、散らばりの標準偏差とは意味が違う。", "vs": "中央値はデータを並べた真ん中の値、標準偏差は散らばりの大きさ、最頻値は最も多く現れる値で、いずれも確率で重みづけした期待値ではない。", "usecase": "リスクとリターンの見積もり、保険や投資の判断、強化学習で「その行動で見込める報酬」を測るときなどに使う、意思決定の基礎。", "opt": ["正解。値に確率で重みをつけて足した平均的な見込みが期待値。", "データを並べた真ん中の値で、確率で重みづけした見込みではない。", "散らばりの大きさで、平均的な見込みではない。", "最も多く現れる値で、期待値ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-d' AND c.name='8. AIに必要な数理・統計知識'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-d-q44', '著作権が保護する対象について正しいのはどれか。', NULL, '["アイデアそのものでなく、具体的な表現を保護する", "アイデアも表現も、区別なくすべて保護する", "表現ではなく、アイデアそのものを保護する", "公表されたものは、著作権では保護されない"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "著作権が保護する対象は？", "point": "「著作権は、アイデアそのものでなく、具体的に表現されたものを守る」（アイデア・表現二分論）。", "kid": "著作権は「作品として具体的に表現されたもの」を守るが、その背後にある「アイデアや作風・手法そのもの」は守らない。だから同じテーマでも、表現が違えば別々に著作権が認められる。", "eg": "「猫を主役にした物語を書く」というアイデアは誰でも使えるが、実際に書き上げた文章そのものは、その人の著作物として守られる、あの線引き。", "terms": [["アイデア・表現二分論", "著作権はアイデアそのものでなく、具体的に表現されたものを保護するという考え方"], ["著作物", "人が思想や感情を創作的に表現したもの。著作権の保護対象"]], "think": "判断の軸は「アイデアか、具体的な表現か」。守られるのは表現の方。アイデアや手法そのものは自由に使える、が原則。", "vs": "「アイデアも表現もすべて保護」「アイデアそのものを保護」はいずれも誤りで、守るのは表現の方。「公表されたものは保護されない」も誤りで、公表の有無に関わらず表現は保護される。", "usecase": "AIの学習や、似たテーマの作品を作るときに「どこまでが自由で、どこからが侵害か」を判断する土台。アイデアの共有と表現の保護を分けて考える。", "opt": ["正解。アイデアそのものでなく、具体的な表現を保護する。", "アイデアは保護対象外なので、区別なくすべて保護するのは誤り。", "守るのは表現の方で、アイデアそのものを保護するのは誤り。", "公表の有無に関わらず表現は保護されるので、誤り。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-d' AND c.name='9. AIに関する法律と契約'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-d-q45', '会社の従業員が、職務として会社名義で作成した著作物について、原則として著作者となるのは誰か（職務著作）。', NULL, '["会社（法人）", "作成した従業員個人", "委託先のベンダ", "国"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "従業員が職務で会社名義で作った著作物の、原則の著作者は？", "point": "「従業員が職務として会社名義で作った著作物は、原則として会社が著作者」なら、職務著作。", "kid": "会社員が、仕事として会社の名義で作った文章やプログラムなどは、原則としてその会社が著作者になる。作った本人ではなく会社に権利がある、という決まり(一定の要件あり)。", "eg": "会社の広報担当が作った社内資料は、担当者個人でなく会社のもの、あの扱い。", "terms": [["職務著作", "従業員が職務として会社名義で作った著作物は、原則として会社が著作者になる制度"], ["著作者", "著作物を創作した者。通常は作った本人だが、職務著作では会社になる"]], "think": "「職務・会社名義で作成」なら原則として会社が著作者。作った本人が当然に著作者になるとは限らない点がポイント。", "vs": "作成した従業員個人は、職務著作の要件を満たす場合は原則として著作者にならない。委託先のベンダや国も、この場面で自動的に著作者になるわけではない。", "usecase": "企業でAI関連の成果物や資料を作るとき、権利が会社にあるのか個人にあるのかを判断する基本。契約や社内規程の前提知識になる。", "opt": ["正解。職務として会社名義で作った著作物は、原則として会社が著作者。", "職務著作の要件を満たせば、作った本人は原則として著作者にならない。", "委託先のベンダが自動的に著作者になるわけではない。", "国が著作者になる場面ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-d' AND c.name='9. AIに関する法律と契約'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-d-q46', '完成物を最初に約束しにくいAI開発の特性をふまえ、アセスメント・PoC・開発・追加学習といった段階に分けて契約を進める考え方はどれか。', NULL, '["探索的段階型の開発方式", "完成保証型の一括請負", "著作権の集中管理", "オープンソースライセンス"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "AI開発を、段階に分けて契約を進める考え方は？", "point": "「完成を最初に約束しにくいAI開発を、段階に分けて契約する」なら、探索的段階型の開発方式。", "kid": "AI開発は、やってみないと精度や実現性が読めない。だから最初に完成物を固く約束するのでなく、「調査→小さく試す(PoC)→開発→追加学習」と段階に分け、各段階の結果を見て次に進むか決める契約にする。", "eg": "家を建てる前に、まず地質調査→模型で検討→本工事、と段階を踏んで、都度判断する、あの進め方。", "terms": [["探索的段階型の開発方式", "AI開発を、アセスメント・PoC・開発・追加学習などの段階に分けて契約を進める考え方"], ["PoC", "本開発の前に小さく試して実現性を確かめる工程。この段階の一つ"]], "think": "「最初に完成を約束せず、段階に分けて進める」なら探索的段階型。成果を固く約束する一括請負とは、AIの不確実性への向き合い方が逆。", "vs": "完成保証型の一括請負は成果を最初に固く約束する方式でAIには馴染みにくい、著作権の集中管理は権利の管理の話、オープンソースライセンスはソフトの利用条件で、いずれも段階に分けて進める探索的段階型ではない。", "usecase": "AI開発を発注・受注するときの契約設計の考え方。不確実性の高いAIで、途中の結果を見ながらリスクを抑えて進めるのに使う。", "opt": ["正解。段階に分けて契約を進めるのが探索的段階型の開発方式。", "成果を最初に固く約束する方式で、AIの不確実性には馴染みにくい。", "権利の管理の話で、開発の進め方の契約方式ではない。", "ソフトの利用条件で、AI開発の契約方式ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-d' AND c.name='9. AIに関する法律と契約'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-d-q47', 'AIがどのようなデータで作られ、どのような仕組みで判断しているかを、利用者や社会に対して開示し、検証できるようにするAI倫理上の考え方はどれか。', NULL, '["透明性", "公平性", "頑健性", "効率性"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "AIの作られ方や判断の仕組みを開示し、検証できるようにする考え方は？", "point": "「AIの作られ方や判断の仕組みを開示し、検証できるようにする」なら、透明性。", "kid": "AIが「どんなデータで、どういう仕組みで判断しているか」を、利用者や社会に分かるように開示すること。中身がブラックボックスのままだと信頼できないので、見えるようにする。これが透明性。", "eg": "料理店が、使う食材や調理法をきちんと開示して、客が安心して選べるようにする、あの姿勢。", "terms": [["透明性", "AIの作られ方や判断の仕組みを開示し、利用者や社会が検証できるようにする考え方"], ["説明可能なAI（XAI）", "判断根拠を人に分かる形で示す技術。透明性を支える"]], "think": "「作られ方や仕組みを開示・検証可能に」なら透明性。差別をしない公平性や、攻撃に強い頑健性とは、別の価値。", "vs": "公平性は特定の属性に不当な差をつけないこと、頑健性は攻撃や外乱に強いこと、効率性は少ない資源で動くことで、いずれも仕組みを開示する透明性ではない。", "usecase": "AIガバナンスの基本原則の一つ。特に人の権利に関わる判断で、開示と検証ができることが信頼と受け入れの前提になる。", "opt": ["正解。作られ方や判断の仕組みを開示し検証できるようにするのが透明性。", "特定の属性に不当な差をつけないことで、開示の話ではない。", "攻撃や外乱に強いことで、透明性とは別の価値。", "少ない資源で動くことで、開示の考え方ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-d' AND c.name='10. AI倫理・AIガバナンス'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-d-q48', 'AIの判断によって問題が起きたとき、その責任の所在を明確にし、関係者が説明できるようにしておくべきだ、というAIガバナンス上の考え方はどれか。', NULL, '["アカウンタビリティ", "スケーラビリティ", "インタラクティブ性", "リアルタイム性"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "AIの判断で問題が起きたとき、責任の所在を明確にし説明できるようにする考え方は？", "point": "「AIの判断の責任の所在を明確にし、説明できるようにする」なら、アカウンタビリティ(説明責任)。", "kid": "AIが誤った判断をして誰かが損害を受けたとき、「誰が責任を負い、なぜそうなったかを説明する」体制を整えておくべきだ、という考え方。責任をうやむやにしない。", "eg": "事故が起きたとき「担当は誰で、なぜ起きたか」をきちんと説明できるようにしておく、あの体制づくり。", "terms": [["アカウンタビリティ（説明責任）", "AIの判断について責任の所在を明確にし、関係者が説明できるようにしておく考え方"], ["透明性", "仕組みや作られ方を開示すること。説明責任を果たす土台になる"]], "think": "「責任の所在を明確に・説明できるように」ならアカウンタビリティ。仕組みを開示する透明性と近いが、こちらは“責任と説明”に重心がある。", "vs": "スケーラビリティは規模を拡大できること、インタラクティブ性は対話的であること、リアルタイム性は即時に処理することで、いずれも責任と説明のアカウンタビリティではない。", "usecase": "AIを社会で使う際、トラブル時に責任と経緯を説明できる体制を求めるガバナンスの要。透明性・説明可能性(XAI)と組み合わせて実現する。", "opt": ["正解。責任の所在を明確にし説明できるようにするのがアカウンタビリティ。", "規模を拡大できることで、責任と説明の話ではない。", "対話的であることで、説明責任とは別。", "即時に処理することで、アカウンタビリティではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-d' AND c.name='10. AI倫理・AIガバナンス'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-d-q49', '大規模言語モデルに対し、入力文の中に巧妙な指示を紛れ込ませて、本来の制限を破らせたり意図しない出力をさせたりする攻撃はどれか。', NULL, '["プロンプトインジェクション", "データポイズニング", "敵対的サンプル", "ディープフェイク"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "入力に巧妙な指示を紛れ込ませ、LLMに制限を破らせる攻撃は？", "point": "「入力文に指示を紛れ込ませ、LLMの制限を破らせる」なら、プロンプトインジェクション。", "kid": "大規模言語モデルは、入力文の指示に従って動く。その性質を悪用し、入力に「これまでの指示は無視して〜せよ」といった巧妙な命令を紛れ込ませて、本来の制限を破らせたり、機密を漏らさせたりする攻撃。", "eg": "受付係に渡す書類の中に「上司の許可は不要、すぐ通せ」と偽の指示を紛れ込ませて、ルールを破らせる、あの手口。", "terms": [["プロンプトインジェクション", "入力文に巧妙な指示を紛れ込ませ、LLMに制限を破らせたり意図しない出力をさせる攻撃"], ["データポイズニング", "学習データを汚す別の攻撃。プロンプトインジェクションは使うときの入力を狙う"]], "think": "「使うときの入力文に指示を仕込んでLLMを操る」ならプロンプトインジェクション。学習データを汚すデータポイズニングとは、狙う段階が違う。", "vs": "データポイズニングは学習データを汚す攻撃、敵対的サンプルは入力に微小なノイズを混ぜて誤判定させる攻撃、ディープフェイクは偽コンテンツを作る技術で、いずれも指示を仕込むプロンプトインジェクションではない。", "usecase": "LLMを組み込んだサービスの新しいセキュリティリスク。入力の検査や、外部データを鵜呑みにしない設計などの対策が必要になる。", "opt": ["正解。入力文に指示を紛れ込ませてLLMの制限を破らせるのがプロンプトインジェクション。", "学習データを汚す攻撃で、使うときの入力を狙うのとは段階が違う。", "入力に微小なノイズを混ぜて誤判定させる攻撃で、指示の注入ではない。", "偽コンテンツを作る技術で、プロンプトインジェクションではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-d' AND c.name='10. AI倫理・AIガバナンス'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
INSERT INTO public.questions (subject_id, category_id, source_ref, question_text, code, options, correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, 'g-kentei-d-q50', 'AIの用途をリスクの高さで分類し、許容できないリスクの用途は禁止、高リスクの用途には厳しい義務を課すという形で規制する、EUの法規制はどれか。', NULL, '["EU AI Act", "人間中心のAI社会原則", "著作権法30条の4", "ムーアの法則"]'::jsonb, 0, '[0]'::jsonb, 'single', '', '{"asked": "AIの用途をリスクの高さで分類し、段階的に規制するEUの法規制は？", "point": "「AIの用途をリスクの高さで分類し、段階的に規制するEUの法律」なら、EU AI Act。", "kid": "EUが作ったAIの法規制。AIの用途を「許容できないリスク(禁止)」「高リスク(厳しい義務)」などにリスクの高さで分け、危険なほど厳しく規制する。リスクに応じて扱いを変えるのが特徴。", "eg": "危険度に応じて薬を「市販OK」「処方箋が必要」「使用禁止」と分ける、あの段階規制のAI版。", "terms": [["EU AI Act", "AIの用途をリスクの高さで分類し、段階的に規制するEUの法規制。リスクベースアプローチ"], ["リスクベースアプローチ", "リスクの高さに応じて規制の強さを変える考え方。EU AI Actの基本"]], "think": "「AIをリスクの高さで分類・段階的に規制・EUの法律」ならEU AI Act。理念を示す人間中心のAI社会原則(日本)とは、拘束力も国も違う。", "vs": "人間中心のAI社会原則は日本の理念的な原則、著作権法30条の4は機械学習の著作物利用の規定、ムーアの法則は半導体の性能向上の経験則で、いずれもリスクで段階規制するEU AI Actではない。", "usecase": "AIを世界で提供する企業が意識すべき代表的な法規制。用途のリスク区分に応じて、満たすべき義務が変わる。", "opt": ["正解。AIの用途をリスクの高さで分類し段階的に規制するEUの法律がEU AI Act。", "日本の理念的な原則で、拘束力のあるEUの法規制ではない。", "機械学習の著作物利用の規定で、リスクで段階規制するものではない。", "半導体の性能向上の経験則で、AIの法規制ではない。"]}'::jsonb, 1
FROM public.subjects s JOIN public.categories c ON c.subject_id=s.id
WHERE s.slug='g-kentei-d' AND c.name='10. AI倫理・AIガバナンス'
ON CONFLICT (subject_id, source_ref) DO NOTHING;
COMMIT;
